package com.remapcamera;

import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.ModifierlessKeybind;

@ConfigGroup("remapCamera")
public interface RemapCameraConfig extends Config
{
	@ConfigSection(
			name = "Camera Remapping",
			description = "Settings for remapping the camera",
			position = 0
	)
	String cameraSection = "camera";

	@ConfigItem(
			position = 1,
			keyName = "cameraRotateRemap",
			name = "Remap camera rotating key",
			description = "When enabled, holding the camera rotating key and moving the mouse will rotate the camera.",
			section = cameraSection
	)
	default boolean cameraRotateRemap()
	{
		return false;
	}

	@ConfigItem(
			position = 2,
			keyName = "cameraRotateKey",
			name = "Camera rotating key",
			description = "Hold this key while moving the mouse to rotate the camera.",
			section = cameraSection
	)
	default ModifierlessKeybind cameraRotateKey()
	{
		return new ModifierlessKeybind(KeyEvent.VK_UNDEFINED, 0);
	}

	@ConfigItem(
			position = 3,
			keyName = "invertCamera",
			name = "Invert camera",
			description = "Inverts the camera rotation direction. Enable this if the camera moves the wrong way.",
			section = cameraSection
	)
	default boolean invertCamera()
	{
		return false;
	}

	@ConfigItem(
			position = 3,
			keyName = "respectDialogues",
			name = "Respect dialogues",
			description = "The plugin will respect dialogues and not run when a dialogue or interface is open.",
			section = cameraSection
	)
	default boolean respectDialogues()
	{
		return false;
	}

	@Range(min = 1, max = 10000)
	@ConfigItem(
			position = 4,
			keyName = "sensitivity",
			name = "Camera sensitivity",
			description = "Mouse sensitivity when rotating the camera. Default is 1440 which is around the same as middle mouse click camera rotation.",
			section = cameraSection
	)
	default int sensitivity()
	{
		return 1440;
	}
}

package com.remapcamera;

import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;

public class RemapCameraListener implements KeyListener, MouseListener
{
	@Inject
	private RemapCameraConfig config;
	@Inject
	private RemapCameraPlugin plugin;

	private volatile boolean cameraRotateKeyPressed = false;

	boolean isCameraRotateKeyPressed()
	{
		return cameraRotateKeyPressed;
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (config.cameraRotateRemap() && config.cameraRotateKey().matches(e))
		{

			if (config.respectDialogues()){
   				if (plugin.isDialogOpen()){
					return;
				}
			}
			cameraRotateKeyPressed = true;
			e.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		if (config.cameraRotateRemap() && cameraRotateKeyPressed && config.cameraRotateKey().matches(e))
		{
			cameraRotateKeyPressed = false;
			e.consume();
		}
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		return e;
	}
}

package com.remapcamera;

import com.google.inject.Provides;
import java.awt.MouseInfo;
import java.awt.Point;
import java.awt.PointerInfo;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
		name = "Remap Camera Rotation",
		description = "Rotate the camera by holding a configurable key and moving the mouse",
		tags = {"camera", "rotate", "remap"}
)
public class RemapCameraPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private KeyManager keyManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private RemapCameraConfig config;

	@Inject
	private RemapCameraListener inputListener;

	private Point lastMousePosition;

	@Override
	protected void startUp() throws Exception
	{
		keyManager.registerKeyListener(inputListener);
		mouseManager.registerMouseListener(inputListener);
		lastMousePosition = null;
	}

	@Override
	protected void shutDown() throws Exception
	{
		keyManager.unregisterKeyListener(inputListener);
		mouseManager.unregisterMouseListener(inputListener);
		lastMousePosition = null;
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (!inputListener.isCameraRotateKeyPressed())
		{
			lastMousePosition = null;
			return;
		}
		if (isDialogOpen()){
			return;
		}

		PointerInfo pointerInfo = MouseInfo.getPointerInfo();
		if (pointerInfo == null)
		{
			return;
		}

		Point currentPos = pointerInfo.getLocation();

		if (lastMousePosition != null)
		{
			int dx = currentPos.x - lastMousePosition.x;
			int dy = currentPos.y - lastMousePosition.y;

			if (dx != 0 || dy != 0)
			{

				double scale = config.sensitivity() / 100.0;
				dx = (int) Math.round(dx * scale);
				dy = (int) Math.round(dy * scale);
				if (config.invertCamera())
				{
					dx = -dx;
					dy = -dy;
				}

				// UPDATED: Yaw scale increased from 2047 to 16383
				client.setCameraYawTarget((client.getCameraYawTarget() + dx) & 16383);

				int currentPitch = client.getCameraPitchTarget();
				// UPDATED: Pitch bounds multiplied by 8 (Old: 128-383 | New: 1024-3064)
				client.setCameraPitchTarget(Math.max(1024, Math.min(3064, currentPitch - dy)));
			}
		}

		lastMousePosition = currentPos;
	}

	/**
	 * Check if a dialog is open that will grab numerical input, to prevent F-key remapping
	 * from triggering.
	 */
	public boolean isDialogOpen()
	{
		// Most chat dialogs with numerical input are added without the chatbox or its key listener being removed,
		// so chatboxFocused() is true. The chatbox onkey script uses the following logic to ignore key presses,
		// so we will use it too to not remap keys.
		return isHidden(InterfaceID.Chatbox.MES_LAYER_HIDE) || isHidden(InterfaceID.Chatbox.CHATDISPLAY)
				// We want to block camera remapping in the bank pin interface too, so it does not interfere with the
				// Keyboard Bankpin feature of the Bank plugin
				|| !isHidden(InterfaceID.BankpinKeypad.UNIVERSE);
	}

	private boolean isHidden(int component)
	{
		Widget w = client.getWidget(component);
		return w == null || w.isSelfHidden();
	}

	@Provides
	RemapCameraConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RemapCameraConfig.class);
	}
}

